#!/usr/bin/env python3
"""Emit the application Deployments/Services. Generated rather than hand-written
so the seven workloads cannot drift in the parts that must be identical (the
Agent host wiring, the tag labels, the probe contract)."""

HEADER = """# ===========================================================================
#  GENERATED by scripts/gen-k8s.py — edit that, re-run it, commit the result.
#
#  Why these three things look the way they do:
#
#  1. DD_AGENT_HOST comes from status.hostIP, not a Service name. The Agent is
#     a DaemonSet and a pod must talk to the Agent ON ITS OWN NODE: routing
#     traces through a Service would load-balance them across nodes and attach
#     the wrong host tags to every span.
#  2. The tags.datadoghq.com/* labels are Unified Service Tagging. The Agent
#     reads them off the pod, which is what makes env/service/version line up
#     across traces, logs, metrics and profiles without per-signal config.
#  3. Every service exposes /healthz and that endpoint touches Postgres. A
#     readiness probe that only proves the process is listening is how the
#     Compose version of this stack once sat dead for three days.
# ===========================================================================
"""

COMMON_ENV = """            - name: DD_AGENT_HOST
              valueFrom: { fieldRef: { fieldPath: status.hostIP } }
            - name: DD_SERVICE
              value: carto-%(svc)s
            - name: POSTGRES_PASSWORD
              valueFrom: { secretKeyRef: { name: carto-secrets, key: POSTGRES_PASSWORD } }
            - name: OTEL_EXPORTER_OTLP_METRICS_ENDPOINT
              value: http://$(DD_AGENT_HOST):4318/v1/metrics
            - name: DD_TAGS
              value: instrumentation:agent
"""

SERVICES = [
    dict(svc="catalogue",  lang="python", port=8080, replicas=2,
         needs=["postgres"], cpu="80m",  mem="192Mi", lim="384Mi"),
    dict(svc="checkout",   lang="python", port=8080, replicas=2,
         needs=["postgres", "catalogue"], cpu="80m", mem="192Mi", lim="384Mi"),
    dict(svc="fulfilment", lang="python", port=8080, replicas=1,
         needs=["postgres"], cpu="60m",  mem="192Mi", lim="384Mi"),
    dict(svc="guardrails", lang="python", port=8080, replicas=2,
         needs=["postgres"], cpu="60m",  mem="192Mi", lim="384Mi",
         tier="ai-governance",
         extra_env=[("GUARDRAIL_AGENT_TOKEN", "secret", "GUARDRAIL_AGENT_TOKEN")],
         cfg=["GUARDRAIL_ENABLED", "GUARDRAIL_BUDGET_USD",
              "GUARDRAIL_APPROVAL_THRESHOLD_AUD", "GUARDRAIL_APPROVAL_TTL_S",
              "GUARDRAIL_POLICY_VERSION"]),
    dict(svc="joy",        lang="python", port=8080, replicas=1,
         needs=["postgres", "guardrails"], cpu="60m", mem="256Mi", lim="512Mi",
         tier="ai",
         extra_env=[("ANTHROPIC_API_KEY", "secret", "ANTHROPIC_API_KEY"),
                    ("AGENT_IDENTITY_TOKEN", "secret", "GUARDRAIL_AGENT_TOKEN")],
         cfg=["JOY_MODEL", "JOY_INTERVAL_S", "JOY_MAX_TOKENS",
              "JOY_DRIVER_ENABLED", "JOY_INJECTION_RATE", "AGENT_ID",
              "GUARDRAILS_URL"],
         llmobs=True),
    dict(svc="bff",        lang="nodejs", port=8080, replicas=2,
         needs=["postgres", "catalogue", "checkout", "fulfilment", "joy", "guardrails"],
         cpu="100m", mem="224Mi", lim="448Mi", tier="bff",
         cfg=["CATALOGUE_URL", "CHECKOUT_URL", "FULFILMENT_URL", "JOY_URL",
              "GUARDRAILS_URL"]),
]

PY_CFG = ["DD_ENV", "DD_VERSION", "DD_LOGS_INJECTION", "DD_TRACE_SAMPLE_RATE",
          "DD_PROFILING_ENABLED", "DD_RUNTIME_METRICS_ENABLED", "DD_APPSEC_ENABLED",
          "DD_APPSEC_SCA_ENABLED", "DD_IAST_ENABLED", "DD_API_SECURITY_ENABLED",
          "DD_APPSEC_AUTO_USER_INSTRUMENTATION_MODE", "DD_TRACE_AGENT_PORT",
          "DD_DYNAMIC_INSTRUMENTATION_ENABLED", "DD_EXCEPTION_REPLAY_ENABLED",
          "DD_CODE_ORIGIN_FOR_SPANS_ENABLED", "INSTRUMENTATION_MODE",
          "POSTGRES_HOST", "POSTGRES_DB", "POSTGRES_USER",
          "CARTO_METRIC_EXPORT_MS", "CARTO_BUSINESS_UNIT", "CARTO_BANNER"]

out = [HEADER]
for s in SERVICES:
    svc, port = s["svc"], s["port"]
    tier = s.get("tier", s["lang"])
    cfg = PY_CFG + s.get("cfg", [])
    env = [COMMON_ENV % {"svc": svc}]
    for k in cfg:
        env.append("            - name: %s\n              valueFrom: "
                   "{ configMapKeyRef: { name: carto-config, key: %s } }\n" % (k, k))
    for name, src, key in s.get("extra_env", []):
        ref = "secretKeyRef: { name: carto-secrets, key: %s }" % key
        env.append("            - name: %s\n              valueFrom: { %s }\n" % (name, ref))
    # dd-trace-js is not auto-loaded by requiring it from main.js -- it must be
    # preloaded before any instrumented module. compose.yaml does this with
    # NODE_OPTIONS on the service block; Kubernetes had no equivalent, so the
    # Node services produced NO traces at all on kind and GKE. The BFF is the
    # request entry point and the minter of txn_id, so its absence broke the
    # one-trace-per-request story exactly where it starts.
    if s["lang"] == "nodejs":
        env.append("            - name: NODE_OPTIONS\n"
                   "              value: -r dd-trace/init\n")

    if s.get("llmobs"):
        env.append("            - name: DD_LLMOBS_ENABLED\n              value: \"true\"\n")
        env.append("            - name: DD_LLMOBS_ML_APP\n              value: carto-joy\n")
        env.append("            - name: DD_LLMOBS_AGENTLESS_ENABLED\n              value: \"false\"\n")

    # initContainers encode the dependency order Compose expressed with
    # depends_on. Kubernetes has no equivalent, and without them a pod that
    # starts before Postgres crash-loops with a confusing connection error
    # instead of waiting.
    init = ""
    if s["needs"]:
        waits = []
        for dep in s["needs"]:
            if dep == "postgres":
                waits.append("            until nc -z postgres 5432; do echo waiting for postgres; sleep 2; done")
            else:
                waits.append("            until nc -z %s 8080; do echo waiting for %s; sleep 2; done" % (dep, dep))
        init = ("      initContainers:\n"
                "        - name: wait-for-deps\n"
                "          image: busybox:1.36\n"
                "          command: ['sh', '-c']\n"
                "          args:\n"
                "          - |\n"
                + "\n".join(waits) + "\n"
                "          resources:\n"
                "            requests: { cpu: 10m, memory: 16Mi }\n")

    out.append("""---
apiVersion: v1
kind: Service
metadata:
  name: %(svc)s
  namespace: carto
  labels:
    app: %(svc)s
    tags.datadoghq.com/service: carto-%(svc)s
spec:
  selector: { app: %(svc)s }
  ports:
    - name: http
      port: %(port)d
      targetPort: %(port)d
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: %(svc)s
  namespace: carto
  labels:
    app: %(svc)s
    app.kubernetes.io/part-of: carto-demo
spec:
  replicas: %(replicas)d
  selector:
    matchLabels: { app: %(svc)s }
  strategy:
    type: RollingUpdate
    rollingUpdate:
      maxUnavailable: 0
      maxSurge: 1
  template:
    metadata:
      labels:
        app: %(svc)s
        tier: %(tier)s
        tags.datadoghq.com/service: carto-%(svc)s
        tags.datadoghq.com/env: prd
        tags.datadoghq.com/version: "0.1.0"
      annotations:
        ad.datadoghq.com/%(svc)s.logs: '[{"source": "%(lang)s", "service": "carto-%(svc)s"}]'
    spec:
      terminationGracePeriodSeconds: 30
%(init)s      containers:
        - name: %(svc)s
          image: carto-%(svc)s:latest
          imagePullPolicy: IfNotPresent
          ports:
            - name: http
              containerPort: %(port)d
          env:
%(env)s          readinessProbe:
            httpGet: { path: /healthz, port: %(port)d }
            initialDelaySeconds: 10
            periodSeconds: 10
            timeoutSeconds: 5
            failureThreshold: 3
          livenessProbe:
            httpGet: { path: /healthz, port: %(port)d }
            initialDelaySeconds: 45
            periodSeconds: 20
            timeoutSeconds: 5
            failureThreshold: 3
          resources:
            requests: { cpu: %(cpu)s, memory: %(mem)s }
            limits:   { memory: %(lim)s }
""" % dict(svc=svc, port=port, replicas=s["replicas"], tier=tier, lang=s["lang"],
           init=init, env="".join(env), cpu=s["cpu"], mem=s["mem"], lim=s["lim"]))

open("k8s/base/20-services.yaml", "w").write("".join(out))
print("wrote k8s/base/20-services.yaml (%d services)" % len(SERVICES))

# ---------------------------------------------------------------------------
#  Postgres init + conf as a ConfigMap.
#
#  Kustomize refuses to read files from outside its own root, so a
#  configMapGenerator pointing at ../../postgres is rejected. Rather than
#  duplicating the SQL under k8s/ (two copies that will drift) or forcing every
#  user onto `kustomize build --load-restrictor LoadRestrictionsNone`, the
#  ConfigMap is GENERATED here from the same postgres/*.sql that Compose
#  mounts. postgres/ stays the single source of truth; re-run this script after
#  editing the seed.
# ---------------------------------------------------------------------------
import os as _os

_FILES = [
    ("00-dbm-init.sql",        "postgres/00-dbm-init.sql"),
    ("10-carto-seed.sql",      "postgres/10-carto-seed.sql"),
    ("20-guardrails-seed.sql", "postgres/20-guardrails-seed.sql"),
]
_CONF = ("postgresql.conf", "postgres/postgresql.conf")


def _block(key, path, indent="    "):
    body = open(path, encoding="utf-8").read()
    # Block scalars cannot represent trailing whitespace on a line reliably;
    # strip it so the round-trip through YAML is byte-faithful.
    lines = [ln.rstrip() for ln in body.split("\n")]
    out = ["  %s: |" % key]
    out += [(indent + ln).rstrip() for ln in lines]
    return "\n".join(out)


parts = ["""# ===========================================================================
#  GENERATED by scripts/gen-k8s.py from postgres/*.sql — do not edit by hand.
#
#  These run ONCE, in lexical order, against an EMPTY data directory. Changing
#  the seed therefore needs the PVC deleted, exactly as it needs the volume
#  deleted under Compose:
#      kubectl -n carto delete sts postgres && kubectl -n carto delete pvc -l app=postgres
# ===========================================================================
---
apiVersion: v1
kind: ConfigMap
metadata:
  name: postgres-init
  namespace: carto
data:"""]
for key, path in _FILES:
    parts.append(_block(key, path))
parts.append("""---
apiVersion: v1
kind: ConfigMap
metadata:
  name: postgres-conf
  namespace: carto
data:""")
parts.append(_block(_CONF[0], _CONF[1]))
open("k8s/base/11-postgres-init.yaml", "w").write("\n".join(parts) + "\n")
print("wrote k8s/base/11-postgres-init.yaml (%d sql files + conf)" % len(_FILES))
